import os, json
from bioblend.galaxy import GalaxyInstance
hist='bbd44e69cb8906b53fe9e0f16f0f5940'
url=os.environ['GALAXY_URL']
with open(os.environ['GALAXY_API_KEY_FILE']) as fh:
    key=fh.read().strip()
gi=GalaxyInstance(url=url, key=key)
files=[('galaxy_q1_generated.ped','RgeneticsData.ped'),('galaxy_q1_generated.map','RgeneticsData.map')]
sessions=[]
for path,name in files:
    uploader=gi.get_tus_uploader(path, metadata={'filename': name}, chunk_size=50_000_000)
    uploader.upload()
    sessions.append((uploader.session_id,name))
payload={
    'history_id': hist,
    'targets': [{
        'destination': {'type':'hdas'},
        'elements': [{
            'src': 'files',
            'ext': 'lped',
            'dbkey': '?',
            'name': 'RgeneticsData',
            'composite': {
                'elements': [
                    {'src':'files','name':'RgeneticsData.ped'},
                    {'src':'files','name':'RgeneticsData.map'},
                ]
            },
        }],
    }],
    'auto_decompress': False,
}
for i,(session_id,name) in enumerate(sessions):
    payload[f'files_{i}|file_data']={'session_id':session_id,'name':name}
resp=gi.tools._post(payload, url='/'.join((gi.url,'tools/fetch')))
print(json.dumps({'jobs':[j.get('id') for j in resp.get('jobs', [])], 'outputs':[o.get('id') for o in resp.get('outputs', [])], 'output_exts':[o.get('file_ext') for o in resp.get('outputs', [])]}))
